select public.prepify_load_bank('Chemistry', 10, $j$[["According to Arrhenius theory, an acid produces which ion in water?",["OH⁻","H⁺","Na⁺","Cl⁻"],"B",1,0,"aea33845af73",0],["According to Arrhenius theory, a base produces which ion in water?",["H⁺","Cl⁻","OH⁻","Na⁺"],"C",1,0,"55b97a874435",0],["Which scientist proposed the Arrhenius theory of acids and bases?",["Dalton","Rutherford","Arrhenius","Bohr"],"C",1,0,"0a98084869a8",0],["Acids generally have a ______ taste.",["Bitter","Sweet","Sour","Salty"],"C",1,0,"8c7b33b3cb93",0],["Bases generally have a ______ taste.",["Sour","Bitter","Sweet","Salty"],"B",1,0,"3a6204b06fbe",0],["An acid turns blue litmus paper:",["Green","Yellow","Red","Black"],"C",1,0,"e7b76ec5e747",0],["A base turns red litmus paper:",["Blue","Green","Yellow","Red"],"A",1,0,"6df65bbaaf9e",0],["Which of the following is a common acid?",["NaOH","KOH","HCl","Ca(OH)₂"],"C",1,0,"bf23faf0a3b3",0],["Which of the following is a common base?",["HNO₃","H₂SO₄","H₃PO₄","NaOH"],"D",1,0,"a613d04fa83d",0],["Sodium hydroxide is commonly used in:",["Soap making","Photography","Food preservation","Medicine"],"A",1,0,"5e9800913c27",0],["Potassium hydroxide is used in making:",["Cement","Liquid soap","Fertilizers","Paints"],"B",1,0,"3373069abcb8",0],["Calcium hydroxide is used in making:",["Mortar and cement","Explosives","Soft drinks","Perfumes"],"A",1,0,"18f27da6b76f",0],["Magnesium hydroxide is commonly used as:",["Fuel","Fertilizer","Antacid","Dye"],"C",1,0,"d4d0a398a50a",0],["A Bronsted-Lowry acid is a:",["Proton acceptor","Electron donor","Proton donor","Salt former"],"C",1,0,"854ed33e513c",0],["A Bronsted-Lowry base is a:",["Proton acceptor","Proton donor","Metal oxide","Salt"],"A",1,0,"f9a005a997da",0],["In the reaction HCl + H₂O → H₃O⁺ + Cl⁻, HCl acts as:",["Base","Acid","Salt","Catalyst"],"B",1,0,"09b6300d3ba9",0],["In the reaction HCl + H₂O → H₃O⁺ + Cl⁻, water acts as:",["Acid","Salt","Base","Metal"],"C",1,0,"5940a032fba7",0],["In the reaction H₂O + NH₃ → NH₄⁺ + OH⁻, NH₃ acts as:",["Acid","Base","Salt","Indicator"],"B",1,0,"6716ac777562",0],["In the reaction H₂O + NH₃ → NH₄⁺ + OH⁻, water acts as:",["Acid","Base","Salt","Alkali"],"A",1,0,"cf754ef8d63e",0],["Water can behave as both an acid and a base. Such substances are called:",["Neutral","Amphoteric","Basic","Acidic"],"B",1,0,"26d67d81ebf6",0],["Which of the following is an amphoteric substance?",["HCl","NaOH","H₂O","HNO₃"],"C",1,0,"98311d98120b",0],["Which acid is used in the manufacture of fertilizers and explosives?",["HCl","H₃PO₄","HNO₃","CH₃COOH"],"C",1,0,"e4f883e789ef",0],["Hydrochloric acid is commonly used for:",["Cleaning metals","Making cement","Food preservation","Photography"],"A",1,0,"0ef510038e10",0],["Acids and bases in aqueous solutions can:",["Conduct electricity","Produce light","Float on water","Become gases"],"A",1,0,"b582ceb672ac",0],["Which ion is responsible for acidic properties?",["Na⁺","OH⁻","H⁺","Cl⁻"],"C",1,0,"ecf7537ba54f",0],["Which ion is responsible for basic properties?",["H⁺","OH⁻","NO₃⁻","SO₄²⁻"],"B",1,0,"d617d5f8bd2a",0],["NaOH dissociates in water to form:",["H⁺ and OH⁻","Na⁺ and OH⁻","Na⁺ and Cl⁻","H⁺ and Cl⁻"],"B",1,0,"de87d8d59088",0],["HCl dissociates in water to form:",["H⁺ and Cl⁻","H⁺ and OH⁻","Na⁺ and Cl⁻","K⁺ and OH⁻"],"A",1,0,"8d2a1d9b6366",0],["Which of the following is a base?",["H₂SO₄","HNO₃","NH₄OH","HCl"],"C",1,0,"d7113c40c0d0",0],["Which of the following is an acid?",["KOH","NaOH","Ca(OH)₂","H₃PO₄"],"D",1,0,"506d57c5a4a5",0],["Which acid is used as an acidulant in food?",["HCl","HNO₃","H₂SO₄","H₃PO₄"],"D",1,0,"509fbac5135a",0],["Bases that are soluble in water are called:",["Acids","Alkalis","Salts","Oxides"],"B",1,0,"d606714e0593",0],["Which of the following is an alkali?",["NaOH","CuO","CO₂","SO₂"],"A",1,0,"95b6025ea2e1",0],["A substance that accepts a proton forms a:",["Negative ion","Positive ion","Neutral atom","Molecule only"],"B",1,0,"ce6d6a5c1a83",0],["After donating a proton, an acid usually forms a:",["Positive ion","Neutral atom","Negative ion","Molecule"],"C",1,1,"35b13ebb99ce",0],["Which of the following is NOT a property of acids?",["Sour taste","Turn blue litmus red","Produce H⁺ ions in water","Turn red litmus blue"],"D",1,0,"4498d33c4c0d",0],["Which of the following is NOT a property of bases?",["Bitter taste","Produce OH⁻ ions in water","Turn red litmus blue","Turn blue litmus red"],"D",1,0,"5a6e38eaf26a",0],["NH₃ behaves as a base because it:",["Donates electrons","Accepts a proton","Produces Cl⁻ ions","Produces H⁺ ions directly"],"B",1,0,"e0991390928f",0],["Which acid is commonly present in laboratory cleaning solutions?",["Hydrochloric acid","Sodium hydroxide","Potassium hydroxide","Calcium hydroxide"],"A",1,0,"f551ef00a27c",0],["The Bronsted-Lowry theory defines acids and bases in terms of:",["Electrons","Neutrons","Protons","Atoms"],"C",1,0,"06f9e6bcefd7",0],["Which pair correctly represents an acid and a base respectively?",["HCl and NaOH","NaOH and HNO₃","KOH and H₂SO₄","NH₄OH and HCl"],"A",1,0,"b3306c352893",0],["Which of the following acids is used in the manufacture of many chemicals, dyes, and paints?",["HCl","H₂SO₄","HNO₃","H₃PO₄"],"B",1,0,"fa5030b0cdf8",0],["The study of acids, bases, and their reactions helps explain:",["Only physical changes","Only nuclear reactions","Many everyday chemical processes","Only biological reactions"],"C",1,0,"ac3faddc3d6c",0],["A student places blue litmus paper into an unknown solution. The paper immediately turns red. The solution most likely contains:",["OH⁻ ions","H⁺ ions","Na⁺ ions","Cl⁻ ions"],"B",5,1,"e69b66a681c2",0],["During an experiment, a solution changes red litmus paper to blue. According to Arrhenius theory, the solution contains a high concentration of:",["H⁺ ions","H₃O⁺ ions","OH⁻ ions","Cl⁻ ions"],"C",5,1,"c9a9c493d4d9",0],["A factory uses a chemical to remove rust from iron surfaces. Which acid is most likely being used?",["H₃PO₄","HCl","NH₄OH","Mg(OH)₂"],"B",5,1,"ea8033554c80",0],["A patient complains of stomach acidity. The doctor recommends milk of magnesia. This substance works because it is a:",["Strong acid","Salt","Base","Metal oxide"],"C",5,1,"5852f2912f75",0],["A chemist adds ammonia to water. The ammonia molecule accepts a proton from water. According to Bronsted-Lowry theory, ammonia behaves as a:",["Salt","Acid","Base","Catalyst"],"C",5,1,"ef8e770b94ce",0],["A student accidentally spills a solution on red litmus paper, but no color change occurs. Which statement is most likely correct?",["The solution is acidic","The solution is basic","The solution may be neutral","The solution contains only H⁺ ions"],"C",5,1,"266facde7f2c",0],["A farmer applies a chemical containing phosphoric acid to improve crop growth. The acid is mainly used in the manufacture of:",["Detergents","Fertilizers","Plastics","Dyes"],"B",5,1,"a15bac98cd8e",0],["In the reaction HCl + H₂O → H₃O⁺ + Cl⁻, the water molecule acts as a proton:",["Donor","Acceptor","Producer","Neutralizer"],"B",5,1,"28c21a3723d4",0],["A student observes that a substance has a bitter taste and turns red litmus blue. The substance is most likely:",["An acid","A salt","A base","A metal"],"C",5,1,"fcc04fc352d7",0],["During an industrial process, nitric acid is selected because of its role in producing fertilizers and explosives. Its chemical formula is:",["H₂SO₄","HCl","HNO₃","H₃PO₄"],"C",5,1,"8d030c4af61c",0],["A solution contains a large number of OH⁻ ions. Which observation would be expected?",["Blue litmus turns red","Red litmus turns blue","Sour taste","Release of H⁺ ions"],"B",5,1,"429af6aae8d8",0],["A chemist identifies a substance as amphoteric. Which behavior confirms this property?",["It reacts only as an acid","It reacts only as a base","It can act as both an acid and a base","It does not react at all"],"C",5,1,"727692984e8a",0],["A laboratory technician is preparing liquid soap. Which base would be most suitable?",["Ca(OH)₂","Mg(OH)₂","KOH","HCl"],"C",5,1,"27af15436335",0],["A student is given 